    'RegisterSimpleRisk'=>'רישום SimpleRisk',
    'RegistrationText'=>'מופעי SimpleRisk רשומים מקבלים באופן מיידי גישה לתוספות (Extras) שדרוג ו-Secure Controls Framework (SCF). תוספת השדרוג מאפשרת לגבות ולשדרג את מופע SimpleRisk שלך בלחיצת כפתור. תוספת Secure Controls Framework (SCF) מספקת מסגרת בקרה משותפת המשולבת בפונקציונליות הממשל התאגידי של SimpleRisk. עם רישום SimpleRisk, פרטי הרישום שלך יישלחו לשרת המתארח על ידי SimpleRisk. פרטי הרישום שיסופקו ישמשו את SimpleRisk כדי להודיע ללקוחות על גרסאות חדשות ועל עדכוני אבטחה. פעולת הרישום של SimpleRisk תצרף אותך לתקשורת השיווקית שלנו, אך תוכל להסיר את עצמך בכל עת באמצעות קישור ביטול המנוי בתקשורת זו. SimpleRisk מכבדת את פרטיות לקוחותיה, והמידע שנמסר לנו במהלך תהליך הרישום ל-SimpleRisk לעולם לא יימכר לצד שלישי.',
