    'IncidentManagementExtraDesc'         => 'תוספת ניהול האירועים מבוססת על מדריך NIST 800-61 לטיפול באירועי אבטחת מחשבים ומספקת יכולות ניהול אירועים בתוך מערכת SimpleRisk.',

