    'RedefineNamingConventionsDesc'       => 'שינוי שם המונחים של SimpleRisk (סיכון, נכס, מסגרת וכו\') בכל הממשק.',
    'RiskConfigurationDesc'               => 'הגדרת כללי ציון סיכון: רמות, תיאבון סיכון, ספי SLA והנוסחאות הקלאסיות / נוסחאות הסיכון עם גורמים תורמים.',
    'RiskAndThreatCatalogDesc'            => 'תחזק את קטלוג ערכי הסיכון והאיומים המשמשים בתפריטים נפתחים.',
    'AddAndRemoveValuesDesc'              => 'ניהול הערכים ברשימות הנפתחות של שדות הסיכון: מיקום, מקור, קטגוריה, צוות, טכנולוגיה ועוד.',
    'AssetValuationDesc'                  => 'הגדרת סולם הערכת שווי הנכסים ודריסות הערכת שווי לכל נכס.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'הוספה, עריכה, השבתה ואיפוס משתמשים; ניהול מדיניות סיסמאות.',
    'RoleManagementDesc'                  => 'הגדירו תפקידים וההרשאות שכל תפקיד מעניק.',
    'TeamManagementDesc'                  => 'צור ונהל צוותים המשמשים לסינון נראות רשומות.',
    'SeparationExtraDesc'                 => 'תוספת ההפרדה מבוססת הצוותים מגבילה את הצפייה בסיכונים למשתמשים החברים בצוות שהסיכון מוקצה לו. במוצר SimpleRisk Core, ללא תוספת זו, כל משתמש יכול לראות כל סיכון.',
    'CustomAuthenticationExtraDesc'       => 'תוספת האימות המותאם אישית מספקת תמיכה באימות Active Directory ו-SAML. במוצר SimpleRisk Core, ללא תוספת זו, האפשרות היחידה היא ליצור משתמשים חדשים במאגר הזהויות של SimpleRisk.',
    'EncryptionExtraDesc'                 => 'תוספת מסד הנתונים המוצפן יוצרת מפתח הצפנה אקראי בגודל AES-256 סיביות ומשתמשת בו להצפנת טקסט רגיש לפני הכנסתו למסד הנתונים של SimpleRisk. כך נמנעת האפשרות לצפות בנתונים או לשנות אותם ללא שימוש ישיר ביישום SimpleRisk.',
    'OrganizationManagementDesc'          => 'תוספת ההיררכיה הארגונית מאפשרת להגדיר מספר יחידות עסקיות שיכולות לכלול כל מספר של צוותים. לאחר מכן ניתן להקצות משתמשים לצוות אחד או יותר תחת יחידות עסקיות שונות. הדבר משפיע על יכולתו של המשתמש לראות ולהשתמש בצוותים, במשתמשים ובנכסים שאינם משויכים אליו.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'מחיקת סיכונים בכמות גדולה. יש להשתמש במשורה - מחיקות הן לצמיתות.',
    'AuditTrailDesc'                      => 'חיפוש וייצוא של יומן הביקורת של המערכת עבור פעולות משתמשים.',
    'ImportExportExtraDesc'               => 'תוספת הייבוא-ייצוא מספקת אפשרות לייבא נתונים אל SimpleRisk על ידי מיפוי שדות בקובץ CSV לשדות במסד הנתונים של SimpleRisk. ניתן להשתמש בה לייבוא תוצאות ביקורת מגיליון אלקטרוני של צד שלישי, תוצאות סריקת פגיעויות מכלי אחר, נכסים מ-CMDB ועוד. התוספת מספקת גם אפשרות לייצא מ-SimpleRisk קובצי CSV המכילים סיכונים, הפחתות סיכון, סקירות או דוח משולב של שלושתם.',
    'JiraExtraDesc'                       => 'תוספת השילוב עם Jira מאפשרת למשתמשים לבצע שילוב דו-כיווני עם מופע Jira. היא מאפשרת לקשר סיכונים לפריטי Jira, וכן לסנכרן את הנתונים, הסטטוס וההערות שלהם.',
    'APIExtraDesc'                        => 'תוספת ה-API מאפשרת ללקוחות להשתמש ב-RESTful API כדי ליצור אינטראקציות מבוססות סקריפטים עם יישומים אחרים, להשיג אוטומציה מתקדמת ולנצל תשתית קיימת.',
    'AdvancedSearchExtraDesc'             => 'תוספת החיפוש המתקדם הופכת את תיבת החיפוש בסרגל העליון לחיפוש אחד על פני סיכונים, מסגרות, בקרות, מסמכים, חריגים, בדיקות, ביקורות, נכסים וקבוצות נכסים, עם דף חיפוש מלא לעבודה עם התוצאות. היא מציגה רק רשומות שהמשתמש רשאי לראות.',
    'AssessmentsExtraDesc'                => 'תוספת הערכת הסיכונים מאפשרת למשתמשים להגדיר אנשי קשר, ליצור שאלות (כולל לוגיקה), להרכיב מספר שאלות בתבנית שאלון, ליצור שאלונים ולשלוח אותם לאנשי קשר, להציג את תוצאות השאלונים, להוסיף סיכונים על סמך תוצאות אלו, להשוות תוצאות לאורך זמן, לייבא ולייצא הערכות מותאמות אישית חיצוניות, ולסקור את מסלול הביקורת של הערכת הסיכונים.',
    'ActiveAssessmentsDesc'               => 'הצגה וניהול של הערכות שנמצאות כעת בתהליך.',
    'WorkflowsExtraDesc'                  => 'תוספת תהליכי העבודה מספקת מנוע תהליכי עבודה חזותי מבוסס אירועים, המבצע אוטומציה של פעולות ניהול סיכונים בתגובה לאירועים בתוך SimpleRisk. ניתן לתכנן תהליכי עבודה המופעלים בעקבות שינויים — כגון הגשת סיכון, עדכונו או סקירתו — כדי לנתב אישורים, להקצות עבודה ולשמור על התקדמות התהליך ללא התערבות ידנית.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'התוסף Secure Controls Framework (SCF) Extra הוא אינטגרציה ישירה בין Secure Controls Framework לבין SimpleRisk. הוא מייבא אל פונקציונליות הממשל התאגידי של SimpleRisk את קטלוג הבקרות של SCF ואת המיפויים שלהן למגוון רחב של מסגרות ציות וסייבר, כך שניתן לאמץ את המסגרות הנדרשות ולנהל את הבקרות שלהן מבלי לבנות אותן ידנית.',

