    'FwLastTestPassed' => 'הבדיקה האחרונה עברה',
    'FwLastTestFailed' => 'הבדיקה האחרונה נכשלה',
    'FwNoEvidence' => 'ישים, אין ראיות',
    'FwMaturityUnderDesired' => 'בגרות מתחת לרצוי',
    'FwScopeAFramework' => 'הגדר היקף למסגרת כדי להחליט',
