    'ApplicabilityScopeNote' => 'החלטה זו חלה רק בתוך "{$framework}". אותה בקרה יכולה להישאר רלוונטית גם במסגרת אחרת.',
    'ApplicabilityAppliesToSelected' => 'היא תתועד עבור {$n} בקרות שנבחרו בדף זה.',
    'ApplicabilityAppliesToAllFiltered' => 'היא תתועד עבור כל {$n} הבקרות התואמות למסננים הנוכחיים, כולל אלה שבדפים אחרים.',
    // Per-state hints under the segmented control. The "applicable" one is the
