    // refers to.
    'SoaMissingFieldsTitle' => 'להצהרה זו חסרים פרטי עמוד השער',
    'SoaMissingScopeStatement' => 'לא נרשמה הצהרת היקף עבור מסגרת זו. הצהרת תחולה צריכה לציין את ההיקף שעבורו היא נערכת.',
    'SoaMissingInclusionJustification' => 'לא נרשמה הצדקת הכללה כברירת מחדל. בקרות רלוונטיות ללא סיכונים מקושרים יקבלו הצהרה כללית במקום ההצהרה שלכם.',
    'SoaEditFrameworkToAdd' => 'הוסיפו אותם במסגרת',

    // Opened from the Reporting Hub, which cannot supply a framework. A picker,
