    'SoaChooseFramework' => 'בחר מסגרת',
    'SoaChooseFrameworkHint' => 'הצהרת תחולה נכתבת על מסגרת אחת בכל פעם.',
    // The picker has a roster but nothing in it. Distinct from "this framework
