    'SoaNoControls' => 'במסגרת זו אין בקרות',
    'SoaNoControlsHint' => 'מפו בקרות למסגרת, והצהרת התחולה שלה תציג אותן.',

    // The second half of the statement-of-applicability launcher's affordance
