    'MotiveHelp' => 'עד כמה קבוצת סוכני האיום הזו מונעת למצוא ולנצל את הפגיעות הזו?' . "\n" . '1 = תגמול נמוך או ללא תגמול כלל' . "\n" . '4 = תגמול אפשרי' . "\n" . '9 = תגמול גבוה',
